import random, time

def call_with_retry(op, idempotency_key, budget=3):
    # WHY: backoff spreads retries, jitter prevents thundering herd,
    # idempotency key lets the server dedup the amplified requests.
    # TRADE-OFF: extra latency and server-side dedup state for safety.
    base_ms = 50
    for attempt in range(budget):
        try:
            # deadline per attempt, not just total: bounds slow-dependency bleed
            return op(timeout_ms=200, idempotency_key=idempotency_key)
        except TransientError:
            if attempt == budget - 1:
                raise
            sleep_ms = base_ms * (2 ** attempt) + random.uniform(0, 50)
            time.sleep(sleep_ms / 1000.0)
